from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse
import hashlib, json, re

class Announcement(HTMLParser):
    def __init__(self):
        super().__init__()
        self.href = None
        self.anchor_text = []
        self.links = []
        self.text = []
        self.hidden = 0
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
        if tag == 'a':
            self.href = dict(attrs).get('href')
            self.anchor_text = []
    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.hidden:
            self.hidden -= 1
        if tag == 'a' and self.href:
            self.links.append((self.href, ' '.join(' '.join(self.anchor_text).split())))
            self.href = None
    def handle_data(self, data):
        if self.hidden:
            return
        self.text.append(data)
        if self.href:
            self.anchor_text.append(data)

root = Path('products/services/public-challenge-fixed-prize')
raw = (root / 'raw/nasa-bps-digital-avatar.html').read_bytes()
source = 'https://www.nasa.gov/directorates/stmd/prizes-challenges-crowdsourcing-program/center-of-excellence-for-collaborative-innovation-coeci/bps-digital-avatar-challenge/'
parser = Announcement()
parser.feed(raw.decode('utf-8', errors='replace'))
text = ' '.join(' '.join(parser.text).split())
links = []
for href, label in parser.links:
    url = urljoin(source, href)
    if urlparse(url).scheme in ('http', 'https') and re.search(r'avatar|herox|challenge\.gov|eligibility|official rules', href + ' ' + label, re.I):
        item = {'url': url, 'label': label}
        if item not in links:
            links.append(item)
match = re.search(r'Submission Deadline\s*:', text, re.I)
record = {'source': source, 'sha256': hashlib.sha256(raw).hexdigest(), 'deadline_context': text[match.start():match.end()+180] if match else None, 'candidate_links': links[:20], 'scope': 'Saved announcement only. A link is a pointer. Confirm deadline, rules, eligibility, judging and payout in the original rules before entering.'}
rendered = json.dumps(record, ensure_ascii=False, indent=2) + '\n'
(root / 'director-avatar-rule-link-readback.json').write_text(rendered, encoding='utf-8')
print(rendered)
